      const initialBed = cave.bedroll, sleeping = cave.state === "sleeping" && initialBed?.sleeper === cave && cave.root.visible;
      const lit = crew.ignite(cave), woke = cave.state === "working" && cave.bedroll === null && initialBed.sleeper === null;
