    const arrives = (row) => row.near && row.faceDot > 0.94 && row.bodyDot > 0.94 && row.layer && !row.insideMirror && row.scene === "hub";
    const preserves = (row) => row.mode === mode && row.responsiveMode === mode && row.selected && row.equipment && row.blurred;
